/// Send `ClearProbe` to every actor thread; on receipt
/// each thread zeros its per-thread message count. Used
/// to mark the warmup → measurement boundary so
/// `stop`'s aggregate excludes warmup messages.
///
/// - Caller-driven: not implicit. The lifecycle API has
///   no built-in warmup phase.
/// - Best-effort: if a thread already exited, the send
///   silently fails. The count of an exited thread is
///   already captured in its `JoinHandle::Output`.
pub fn reset_count(&self) {
    if let Some(senders) = self.senders.as_ref() {
        for tx in senders {
            let _ = tx.send(SignalZC::ClearProbe);
        }
    }
}

/// Read the current aggregate per-thread count without
/// stopping. Sends a `QueryCount(reply)` signal to every
/// actor; each thread replies with its current local
/// `u64` over the reply channel and continues running.
///
/// - Mid-flight: actors keep processing messages between
///   `query_count` and the next call, so two successive
///   reads will not match. The returned value is a
///   point-in-time aggregate, not a snapshot of a stopped
///   world.
/// - Best-effort: if a thread already exited (channel
///   closed), its send fails and is skipped. The recv
///   loop only waits on the actors that accepted the
///   query, so a dead thread can't deadlock the caller.
/// - Aggregation uses `saturating_add` (matches
///   [`Handle::stop`]).
pub fn query_count(&self) -> u64 {
    let (tx, rx) = mpsc::channel::<u64>();
    let mut sent: usize = 0;
    if let Some(senders) = self.senders.as_ref() {
        for s in senders {
            if s.send(SignalZC::QueryCount(tx.clone())).is_ok() {
                sent += 1;
            }
        }
    }
    drop(tx);
    let mut total: u64 = 0;
    for _ in 0..sent {
        if let Ok(c) = rx.recv() {
            total = total.saturating_add(c);
        }
    }
    total
}

