/// `query_count` reads the aggregate per-thread count
/// without stopping. Two successive reads across a run
/// window are monotonic non-decreasing; `stop`'s total
/// is at least the last queried value.
#[test]
fn lifecycle_query_count_monotonic() {
    let pool: Pool = Pool::new(64, 4);
    let mut rt = RuntimeZC::new(pool.clone());
    let mut mgr = ActorManager::new("test.query");
    let a = mgr.add(PingPong { peer: 1 });
    let _b = mgr.add(PingPong { peer: 0 });
    let initial = vec![(a, pool.get_msg(8).expect("seed"))];
    let handle = rt.startup(&mut mgr, initial, &[]);
    handle.run(Duration::from_millis(20));
    let first = handle.query_count();
    handle.run(Duration::from_millis(20));
    let second = handle.query_count();
    let total = handle.stop();
    assert!(first > 0, "expected nonzero first query, got {first}");
    assert!(
        second >= first,
        "expected second >= first, got first={first} second={second}"
    );
    assert!(
        total >= second,
        "expected total >= second, got total={total} second={second}"
    );
}

/// `query_count` after `reset_count` reflects only the
/// post-reset traffic: it is bounded above by `stop`'s
/// total and below by zero, and `stop`'s total drops the
/// pre-reset window.
#[test]
fn lifecycle_query_count_after_reset() {
    let pool: Pool = Pool::new(64, 4);
    let mut rt = RuntimeZC::new(pool.clone());
    let mut mgr = ActorManager::new("test.query.reset");
    let a = mgr.add(PingPong { peer: 1 });
    let _b = mgr.add(PingPong { peer: 0 });
    let initial = vec![(a, pool.get_msg(8).expect("seed"))];
    let handle = rt.startup(&mut mgr, initial, &[]);
    handle.run(Duration::from_millis(20));
    handle.reset_count();
    handle.run(Duration::from_millis(20));
    let queried = handle.query_count();
    let total = handle.stop();
    assert!(queried > 0, "expected nonzero post-reset query, got {queried}");
    assert!(
        total >= queried,
        "expected total >= queried, got total={total} queried={queried}"
    );
}

