    // 8 s of the sampling phase, plus criterion's own internal
    // warmup (a handful of calls).
    group.measurement_time(Duration::from_secs(10));
    group.sample_size(50);
    group.bench_function("pingpong", |b| {
        b.iter_custom(|iters| {
