///   thread count over `reply` and continues running. Probe
///   state (if any) is untouched.
/// - `Shutdown` — runtime injects after the measurement
///   window; actor exits its `recv` loop on receipt.
enum SignalZC<S: BufRefStore> {
    User(PooledMsg<S>),
    ClearProbe,
    QueryCount(Sender<u64>),
    Shutdown,
