//! Goalzc binary: two zerocopy actors, each on its own thread,
//! ping-ponging a pool-backed `PooledMsg` (handler view: `&[u8]`)
//! over `std::sync::mpsc` channels for a caller-supplied
//! duration in seconds, after an optional warmup window.
//! Smoke generator for the pool-backed payload path: prints
//! messages-handled / aggregate throughput plus the `pinning:`
//! line if `--pin` was set.
//!
//! No diagnostic instrumentation in this version. Probing
//! re-enters post-`0.6.0` via an actor-wrapper trait or
//! `TProbe::Counter` (out of scope here).
//!
//! Compared to goal2 (unit `Message`), goalzc exercises the
//! `Pool` + `PooledMsg` path: every dispatch costs one `pool.get`
//! plus one drop-back. `--size N` sweeps payload size; pool is
//! sized for ping-pong steady state (2 buffers in flight) with
//! headroom (4 buffers) so a wakeup race never starves.
//!
//! Usage: `goalzc --help`

use std::time::Duration;

use actor_x1::actor_manager::{ActorManager, ActorZC, ContextZC};
use actor_x1::pool::{BufRefStore, Pool};
use actor_x1::report;
use actor_x1::runtime_zc::RuntimeZC;
use clap::Parser;
use tprobe::fmt_commas;

/// Zerocopy ping-pong actor: on every inbound message, fabricate
/// a reply of the same length from the pool and forward it to
/// the configured peer. Drops the inbound `PooledMsg` after the
/// handler returns (runtime-owned), which returns its buffer to
/// the pool — so per dispatch we see exactly one pool `get` +
/// one pool `put`.
struct PingPongZC {
    peer_id: u32,
}

impl<S: BufRefStore> ActorZC<S> for PingPongZC {
    /// Reply with a same-sized buffer to `self.peer_id`. Never blocks.
    fn handle_message(&mut self, ctx: &mut dyn ContextZC<S>, msg: &[u8]) {
        let reply = ctx.get_msg(msg.len()).expect("get_msg should succeed"); // OK: pool sized for ping-pong steady state (2 in flight; 4 capacity)
        ctx.send(self.peer_id, reply);
    }
}

/// CLI for goalzc: two-thread two-actor zerocopy ping-pong
/// smoke generator. Reports aggregate throughput.
#[derive(Parser, Debug)]
#[command(
    version,
    about,
    long_about = None,
    max_term_width = 80,
    before_help = concat!(env!("CARGO_PKG_NAME"), " ", env!("CARGO_PKG_VERSION")),
)]
struct Cli {
    /// Measurement window in seconds (runs after warmup).
    #[arg(value_parser = report::parse_non_negative_secs)]
    duration_s: f64,

    /// Warmup duration in seconds before measurement. Runs
    /// the same dispatch loop; per-thread counts are zeroed
    /// at the warmup → measurement boundary via
    /// `Handle::reset_count` so reported throughput reflects
    /// only the measurement window.
    #[arg(short = 'w', long, default_value_t = 0.5, value_parser = report::parse_non_negative_secs)]
    warmup: f64,

    /// Message payload size in bytes. Pool is built with this
    /// `msg_size`, so `get_msg(size)` calls inside the handler
    /// always pass the bound check by construction. Must be
    /// `>= 1`.
    #[arg(short = 's', long, default_value_t = 64, value_parser = parse_positive_size)]
    size: u32,

    /// Pin each actor thread to a logical CPU. Accepts a
    /// comma-separated / range list; actor `i` pins to
    /// `pin[i % pin.len()]`. Examples: `--pin 0,1` pairs two
    /// actors to two CPUs; `--pin 0` oversubscribes both onto
    /// one core. Tightens stdev by eliminating OS thread
    /// migration noise.
    #[arg(short = 'p', long)]
    pin: Option<String>,
}

/// `value_parser` helper: parse a positive (>=1) `u32`. Local
/// to goalzc — only this bin has a payload-size flag, so it
/// doesn't belong in the shared `report` module.
fn parse_positive_size(s: &str) -> Result<u32, String> {
    let v: u32 = s
        .parse()
        .map_err(|e: std::num::ParseIntError| e.to_string())?;
    if v == 0 {
        Err(format!("'{s}' must be >= 1"))
    } else {
        Ok(v)
    }
}

/// Parse CLI, run two zerocopy ping-pong actors on their own
/// threads via the lifecycle API, print aggregate throughput.
fn main() {
    let cli = Cli::parse();
    report::print_banner();

    // Pool sized for ping-pong steady state (2 in flight) with
    // headroom; `Pool::new(size, 4)` makes the `--size` runtime
    // bound auto-satisfied since `pool.msg_size() == size`.
    let pool: Pool = Pool::new(cli.size, 4);
    let mut rt = RuntimeZC::new(pool.clone());
    let mut mgr = ActorManager::new("goalzc.dispatch");
    let a_id = mgr.add(PingPongZC { peer_id: 1 });
    let b_id = mgr.add(PingPongZC { peer_id: 0 });
    assert_eq!((a_id, b_id), (0, 1));

    let initial = vec![(
        a_id,
        pool.get_msg(cli.size as usize).expect("seed get_msg"), // OK: fresh pool with capacity 4 satisfies a single get
    )];

    let pin_cores = report::parse_pin_cores(cli.pin.as_deref());

    let n_actors = 2;
    let handle = rt.startup(&mut mgr, initial, &pin_cores);
    handle.run(Duration::from_secs_f64(cli.warmup));
    handle.reset_count();
    handle.run(Duration::from_secs_f64(cli.duration_s));
    let total_count = handle.stop();

    let mmps = total_count as f64 / cli.duration_s / 1e6;
    println!(
        "goalzc: {} messages in {:.3}s ({mmps:.3} M msg/s, {n_actors} actors, size={size} B)",
        fmt_commas(total_count),
        cli.duration_s,
        size = cli.size,
    );
    report::print_pinning(&pin_cores, n_actors);
}

//! goalzc-crit: criterion smoke benchmark for the lifecycle
//! API on the pool-backed payload path.
//!
//! Drives the same two-thread two-actor zerocopy ping-pong
//! workload `goalzc` runs, via the lifecycle API
//! ([`RuntimeZC::startup`] → [`Handle::run`] →
//! [`Handle::reset_count`] / [`Handle::query_count`] →
//! [`Handle::stop`]). Invoked as
//! `cargo bench --bench goalzc-crit` from `crates/actor-x1`.
//!
//! Probe-free by construction (the runtime no longer ships a
//! probed path; that re-enters post-`0.6.0` via an actor-
//! wrapper trait or `TProbe::Counter`).
//!
//! Shape note (amortized in `0.6.0-4`). `Handle::run` is
//! wall-clock driven — actor threads ping-pong freely for a
//! caller-supplied run window; there is no "do N messages"
//! primitive. To fit criterion's iteration-count model, the
//! benchmark starts up the actor mesh once outside
//! `iter_custom`, runs an initial warmup, then each
//! `iter_custom` call does `reset_count → run(measurement) →
//! query_count` against the still-live mesh. The per-iter
//! time is `measurement * iters / measurement_count` so
//! criterion's per-iter estimate reflects per-message time
//! during the measurement window only. Each iteration is
//! "one `handle_message` call at either actor".
//! `Throughput::Elements(1)` makes criterion's throughput
//! summary read as msgs / s.
//!
//! The amortization drops the per-sample
//! `startup` + thread-spawn + `stop` + join overhead (~a few
//! ms each); the bench-vs-bin gap from `0.6.0-2` (~11%)
//! collapses if that overhead was the cause.
//!
//! Compare the reported per-message time / throughput against
//! `goalzc`'s `M msg/s` line at the same `--size` and pinning
//! (default: unpinned, `--size 64`).

use std::time::Duration;

use actor_x1::actor_manager::{ActorManager, ActorZC, ContextZC};
use actor_x1::pool::{BufRefStore, Pool};
use actor_x1::runtime_zc::RuntimeZC;
use criterion::{Criterion, Throughput, criterion_group, criterion_main};

/// Bench-local zerocopy ping-pong actor: forwards a same-sized
/// reply on each message. Mirrors `goalzc`'s `PingPongZC`.
struct PingPongZC {
    peer_id: u32,
}

impl<S: BufRefStore> ActorZC<S> for PingPongZC {
    /// Reply with a same-sized buffer to `self.peer_id`. Never blocks.
    fn handle_message(&mut self, ctx: &mut dyn ContextZC<S>, msg: &[u8]) {
        let reply = ctx.get_msg(msg.len()).expect("get_msg should succeed"); // OK: pool sized for ping-pong steady state (2 in flight; 4 capacity)
        ctx.send(self.peer_id, reply);
    }
}

/// Spin up the actor mesh once, warm up, then per
/// `iter_custom` call: reset counts, run a fixed window,
/// query, scale to iters. Handle drops at end of the bench
/// function (silent shutdown).
fn bench_goalzc(c: &mut Criterion) {
    const SIZE: u32 = 64;
    let mut group = c.benchmark_group("goalzc-crit");
    group.throughput(Throughput::Elements(1));
    // Per sample: 100 ms measurement + a `reset_count` +
    // `query_count` round trip (~µs). 50 samples * ~100 ms ≈
    // 5 s of sampling phase, plus a one-shot 50 ms warmup
    // outside `iter_custom`.
    group.measurement_time(Duration::from_secs(6));
    group.sample_size(50);
    group.bench_function("pingpong", |b| {
        let pool: Pool = Pool::new(SIZE, 4);
        let mut rt = RuntimeZC::new(pool.clone());
        let mut mgr = ActorManager::new("goalzc-crit");
        let a_id = mgr.add(PingPongZC { peer_id: 1 });
        let _b_id = mgr.add(PingPongZC { peer_id: 0 });
        let initial = vec![(
            a_id,
            pool.get_msg(SIZE as usize).expect("seed get_msg"), // OK: fresh pool with capacity 4 satisfies a single get
        )];
        let handle = rt.startup(&mut mgr, initial, &[]);
        // One-shot warmup so the first sample sees the same
        // steady state as the rest.
        handle.run(Duration::from_millis(50));

        b.iter_custom(|iters| {
            let measurement = Duration::from_millis(100);
            handle.reset_count();
            handle.run(measurement);
            let measurement_count = handle.query_count();

            // Scale: `measurement` of wall time produced
            // `measurement_count` messages (post-reset).
            // Criterion wants total time for `iters`
            // iterations, so project linearly.
            let per_msg_ns = measurement.as_nanos() as u64 / measurement_count.max(1);
            Duration::from_nanos(per_msg_ns.saturating_mul(iters))
        });
        // `handle` drops here → silent shutdown, pool drains.
    });
    group.finish();
}

criterion_group!(benches, bench_goalzc);
criterion_main!(benches);

